import { Link } from '../ui/link';
import { Text } from '../ui/text';
import { formatTweetText } from './TweetEntities';
import { formatProfilePictureUrl } from '~/utils/image';
import { Box, Divider, HStack, Stack, styled } from 'styled-system/jsx';
import type { PrunedTweet } from '~/utils/prune-tweets';

interface TweetProps {
  tweet: PrunedTweet;
  hideBottom?: boolean;
  hideInfo?: boolean;
  showLine?: boolean;
  quoted?: boolean;
}

export function Tweet({ tweet, hideBottom, hideInfo, showLine, quoted }: TweetProps) {
  const tweetDate = new Date(tweet.createdAt);
  const today = new Date();
  const isToday =
    tweetDate.getDate() === today.getDate() &&
    tweetDate.getMonth() === today.getMonth() &&
    tweetDate.getFullYear() === today.getFullYear();

  const dateTimeOptions: Intl.DateTimeFormatOptions = {
    year: 'numeric',
    month: 'numeric',
    day: 'numeric'
  };

  if (isToday) {
    dateTimeOptions.hour = '2-digit';
    dateTimeOptions.minute = '2-digit';
  }

  return (
    <Box
      className="tweet"
      data-tweet-id={tweet.id}
      cursor="pointer"
      display="flex"
      borderBottomWidth={hideBottom ? '0' : '1px'}
      borderColor="border.default"
      px={quoted ? 0 : '4'}
      pt={hideInfo || quoted ? 0 : '4'}
      pb={hideBottom || quoted ? 0 : '4'}
      transitionDuration="200ms"
      transitionProperty="colors"
      _hover={{ bg: 'bg.subtle' }}
    >
      <Link
        href={tweet.url}
        target="_blank"
        rel="noopener noreferrer"
        display="flex"
        gap="3"
        alignItems="flex-start"
        w="full"
        textDecoration="unset"
        _hover={{ textDecoration: 'unset' }}
      >
        <Stack gap="0" flexShrink="0" alignItems="center" w={quoted ? '8' : '12'} h="full">
          {!hideInfo && (
            <styled.img
              src={formatProfilePictureUrl(tweet.author.profilePicture)}
              alt={tweet.author.name}
              objectFit="cover"
              borderRadius="full"
              w={quoted ? '8' : '12'}
              h={quoted ? '8' : '12'}
            />
          )}
          {showLine && (
            <Box
              flex="1"
              borderLeft="3px solid"
              borderLeftColor="border.muted"
              height="full"
              mb={!hideBottom ? '8' : 0}
            ></Box>
          )}
        </Stack>
        <Stack gap="0" direction="column" flexGrow="1" minW="0" h="full" overflow="hidden">
          {!hideInfo && (
            <HStack gap="1" alignItems="center" mb="0.5" flexWrap="wrap">
              <HStack flexGrow="1" alignItems="center">
                <Text
                  color="fg.default"
                  textOverflow="ellipsis"
                  textWrap="nowrap"
                  fontSize={quoted ? 'sm' : 'base'}
                  fontWeight="bold"
                  overflow="hidden"
                >
                  {tweet.author.name}
                </Text>
                <Text
                  color="fg.muted"
                  textOverflow="ellipsis"
                  textWrap="nowrap"
                  fontSize={quoted ? 'xs' : 'sm'}
                  overflow="hidden"
                >
                  @{tweet.author.userName}
                </Text>
              </HStack>
              <Text color="fg.muted" fontSize={quoted ? 'xs' : 'sm'}>
                {tweetDate.toLocaleString([], dateTimeOptions)}
              </Text>
            </HStack>
          )}
          <Text
            flex="1"
            w="full"
            h="full"
            mt={hideInfo ? '4' : 0}
            color="fg.default"
            wordBreak="break-word"
            fontSize={quoted ? 'sm' : 'base'}
            whiteSpace="pre-wrap"
          >
            {formatTweetText(tweet.text, tweet.entities)}
          </Text>
          {(tweet.quoted_tweet || tweet.retweeted_tweet) && (
            <Box border="1px solid" borderColor="border.default" rounded="xl" mt="2" p={2}>
              {tweet.retweeted_tweet && <Tweet tweet={tweet.retweeted_tweet} hideBottom quoted />}
              {tweet.quoted_tweet && <Tweet tweet={tweet.quoted_tweet} hideBottom quoted />}
            </Box>
          )}

          {hideBottom && !quoted && <Divider mt="4" />}
          {!hideBottom && (
            <HStack justifyContent="space-between" h="full" mt="2" color="fg.muted">
              <HStack cursor="pointer" justifyContent="center" alignItems="center" spaceX="1">
                <svg
                  className="w-4 h-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth="2"
                    d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"
                  ></path>
                </svg>
              </HStack>
              <HStack cursor="pointer" justifyContent="center" alignItems="center" spaceX="1">
                <svg
                  className="w-4 h-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth="2"
                    d="M7 16V4m0 0L3 8m4-4l4 4m6 0v12m0 0l4-4m-4 4l-4-4"
                  ></path>
                </svg>
              </HStack>
              <HStack cursor="pointer" justifyContent="center" alignItems="center" spaceX="1">
                <svg
                  className="w-4 h-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth="2"
                    d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"
                  ></path>
                </svg>
              </HStack>
              <HStack cursor="pointer" justifyContent="center" alignItems="center" spaceX="1">
                <Link href={tweet.twitterUrl} target="_blank" rel="noopener noreferrer">
                  <svg
                    className="w-4 h-4"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                    xmlns="http://www.w3.org/2000/svg"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth="2"
                      d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.367 2.684 3 3 0 00-5.367-2.684z"
                    ></path>
                  </svg>
                </Link>
              </HStack>
              <Box />
            </HStack>
          )}
        </Stack>
      </Link>
    </Box>
  );
}
